const item = $input.first();
if (!item) return [];
const input = item.json || {};
const normalize = key => String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
const get = (...names) => {
  const keys = names.map(normalize);
  for (const [key, value] of Object.entries(input)) {
    if (keys.includes(normalize(key))) return String(value ?? '').trim();
  }
  return '';
};
const name = get('Student Name','student_name');
const email = get('Email','Email Address','student_email');
const professor = get('Professor Profile URL','Professor / Profile URL','professor_url','Profile_URL');
const field = get('Target Field','target_field');
const degree = get('Target Degree','target_degree','degree_level');
const cv = get('CV','Upload CV','CV File','upload_cv');
const letter = get('Motivation Letter','Upload Motivation Letter','Motivation Letter File','upload_motivation_letter');
if (!name) throw new Error('Student Name is required.');
if (!/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(email)) throw new Error('One valid student Email is required.');
if (!/^https?:\/\/[^\s/]+(?:\/[^\s]*)?$/i.test(professor)) throw new Error('A valid Professor Profile URL is required.');
if (!field || !degree) throw new Error('Target Field and Target Degree are required.');
const driveId = value => {
  const m = String(value).match(/^https:\/\/drive\.google\.com\/(?:file\/d\/([A-Za-z0-9_-]{10,})|(?:open|uc)\?(?:[^#]*&)?id=([A-Za-z0-9_-]{10,}))(?:[/?&#]|$)/i);
  return m ? (m[1] || m[2]) : '';
};
const cvId = driveId(cv), letterId = driveId(letter);
if (!cvId || !letterId) throw new Error('CV and Motivation Letter must each be a Google Drive PDF link.');
item.json = {
  'Student Name': name, 'Email': email, 'Professor Profile URL': professor,
  'Target Field': field, 'Target Degree': degree, 'CV': cv, 'Motivation Letter': letter,
  professor_url: professor, target_field: field, target_degree: degree, degree_level: degree,
  cv_url: cv, motivation_letter_url: letter, cv_file_id: cvId, motivation_letter_file_id: letterId
};
return [item];

const cv = $('Download CV').first().binary?.data;
const letter = $('Download Motivation Letter').first().binary?.data;
if (!cv || !letter) throw new Error('Both downloaded PDFs are required for the draft attachments.');
return [{ json: $input.first().json, binary: { cv, motivation_letter: letter } }];
